DO $$
DECLARE
  rec RECORD;
  cur_status INT;
  cur_attendee INT;
BEGIN
  FOR rec IN SELECT * FROM attendance_requests ORDER BY request_id LOOP
    SELECT status, attendee_id INTO cur_status, cur_attendee FROM sessions WHERE session_id = rec.session_id;
    IF rec.request_type = 1 AND cur_status = 0 THEN
      UPDATE sessions SET status = 1, attendee_id = rec.client_id WHERE session_id = rec.session_id;
    ELSIF rec.request_type = 2 AND cur_status = 1 AND cur_attendee = rec.client_id THEN
      UPDATE sessions SET status = 0, attendee_id = NULL WHERE session_id = rec.session_id;
    ELSIF rec.request_type = 3 AND cur_status = 1 AND cur_attendee = rec.client_id THEN
      UPDATE sessions SET status = 2 WHERE session_id = rec.session_id;
    END IF;
  END LOOP;
END $$;
SELECT * FROM sessions ORDER BY session_id;
